window.checkGaveAIAuth = async function() {
var auth = window.GMT_FIREBASE_AUTH;
if (!auth) {
alert("GaveAI is not ready yet. Please refresh the page and try again.");
return false;
}
var user = auth.currentUser;
if (user) {
window.GMT_CURRENT_USER = user;
return true;
}
user = await new Promise(function(resolve) {
var resolved = false;
var unsubscribe = auth.onAuthStateChanged(function(currentUser) {
if (!resolved) {
resolved = true;
try { unsubscribe(); } catch (e) {}
resolve(currentUser || null);
}
});
setTimeout(function() {
if (!resolved) {
resolved = true;
try { unsubscribe(); } catch (e) {}
resolve(auth.currentUser || null);
}
}, 3000);
});
if (!user) {
alert("1, Go to: Dashboard/Network\n2,Please log in to your account if you already created one or create one to use AI tools");
return false;
}
window.GMT_CURRENT_USER = user;
return true;
};
window.getGMTFirebaseToken = async function () {
var auth = window.GMT_FIREBASE_AUTH;
if (!auth) {
throw new Error("GaveAI Firebase Authentication is not initialized.");
}
var user = auth.currentUser;
if (!user) {
user = await new Promise(function (resolve) {
var resolved = false;
var unsubscribe = auth.onAuthStateChanged(function (currentUser) {
if (!resolved) {
resolved = true;
try { unsubscribe(); } catch (e) {}
resolve(currentUser || null);
}
});
setTimeout(function () {
if (!resolved) {
resolved = true;
try { unsubscribe(); } catch (e) {}
resolve(auth.currentUser || null);
}
}, 3000);
});
}
if (!user) {
throw new Error("Please log in to your account if you already created one or create one to use AI tools.");
}
window.GMT_CURRENT_USER = user;
var token = await user.getIdToken(false);
if (!token) {
token = await user.getIdToken(true);
}
if (!token) {
throw new Error("Unable to obtain Firebase authentication token.");
}
return token;
};
async function getGaveAIAuthHeaders(isFormData) {
const token = await window.getGMTFirebaseToken();
const headers = {
"Authorization": "Bearer " + token,
"Accept": "application/json"
};
if (!isFormData) {
headers["Content-Type"] = "application/json";
}
return headers;
}
