const el = document.getElementById("aiCreditsDisplay");
if (!el) return;
const count = Math.max(0, Number(remaining) || 0);
if (count > 0) {
el.innerHTML = '<span>🎬 Free Video: ' + count + ' Available</span><span style="margin-left:10px;font-weight:600;opacity:.95;">Create images, videos, stories and complete connected videos with AI.</span>';
} else {
el.innerHTML = '<span>🎬 Free Video: Used</span><span style="margin-left:10px;font-weight:600;opacity:.95;">Create images, videos, stories and complete connected videos with AI.</span>';
}
}
