if (input) { input.value = actionText; window.sendAiMessage(false); }
};
const storyboardScenes = [];
let storyboardNextId = 1;
let storyboardActiveSceneId = null;
window.storyboardGetActiveSceneId = function() {
if (storyboardActiveSceneId !== null && storyboardScenes.some(scene => scene.id === storyboardActiveSceneId)) { return storyboardActiveSceneId; }
if (storyboardScenes.length > 0) { storyboardActiveSceneId = storyboardScenes[0].id; return storyboardActiveSceneId; }
return null;
};
window.storyboardSetActiveScene = function(sceneId) {
const scene = storyboardScenes.find(s => s.id === sceneId);
if (!scene) return;
storyboardActiveSceneId = sceneId;
document.querySelectorAll('.sb-scene-card').forEach(card => { card.classList.toggle('active', Number(card.dataset.sceneId) === Number(sceneId)); });
};
window.openStoryboard = async function() {
if (!(await window.checkGaveAIAuth())) return;
const overlay = document.getElementById('storyboardOverlay');
if (overlay) {
overlay.classList.add('open');
if (storyboardScenes.length === 0) { window.storyboardAddScene(); } else { window.storyboardRenderScenes(); }
}
};
window.closeStoryboard = function() {
const overlay = document.getElementById('storyboardOverlay');
if (overlay) overlay.classList.remove('open');
};
window.storyboardAddScene = function() {
const newSceneId = storyboardNextId++;
storyboardScenes.push({ id: newSceneId, prompt: '', duration: 5, imageUrl: '', firstFrameImage: '', lastFrameImage: '', videoUrl: '', voiceText: '', dialogue: '', narration: '', voiceEmotion: '', voiceSpeed: 1.0, musicPrompt: '', musicVolume: 0.7, sfxPrompt: '', sfxVolume: 0.7, ambiencePrompt: '', ambienceVolume: 0.5, frameWidth: 80, frameHeight: 80 });
storyboardActiveSceneId = newSceneId;
window.storyboardRenderScenes();
};
window.storyboardDeleteScene = function(sceneId) {
const idx = storyboardScenes.findIndex(s => s.id === sceneId);
if (idx > -1) {
storyboardScenes.splice(idx, 1);
if (storyboardScenes.length === 0) { storyboardActiveSceneId = null; }
else if (storyboardActiveSceneId === sceneId) { const nextScene = storyboardScenes[Math.min(idx, storyboardScenes.length - 1)]; storyboardActiveSceneId = nextScene.id; }
window.storyboardRenderScenes();
}
};
window.storyboardMoveScene = function(sceneId, direction) {
const idx = storyboardScenes.findIndex(s => s.id === sceneId);
if (idx === -1) return;
const newIdx = idx + direction;
if (newIdx < 0 || newIdx >= storyboardScenes.length) return;
const temp = storyboardScenes[idx];
storyboardScenes[idx] = storyboardScenes[newIdx];
storyboardScenes[newIdx] = temp;
storyboardActiveSceneId = sceneId;
window.storyboardRenderScenes();
};
let storyboardFrameResizeState = null;
window.storyboardApplyFrameVisual = function(sceneId) {
const scene = storyboardScenes.find(function(item) {
return Number(item.id) === Number(sceneId);
});
if (!scene) return;
const frame = document.querySelector(
".sb-composition-frame[data-scene-frame='" + sceneId + "']"
);
if (!frame) return;
const width = Math.max(35, Math.min(100, Number(scene.frameWidth || 80)));
const height = Math.max(35, Math.min(100, Number(scene.frameHeight || 80)));
scene.frameWidth = width;
scene.frameHeight = height;
frame.style.width = width + "%";
frame.style.height = height + "%";
const label = frame.querySelector(".sb-composition-frame-label");
if (label) {
label.textContent = "Composition Frame " + Math.round(width) + "% × " + Math.round(height) + "%";
}
};
window.storyboardStartFrameResize = function(sceneId, edge, event) {
if (!event) return;
event.preventDefault();
event.stopPropagation();
const scene = storyboardScenes.find(function(item) {
return Number(item.id) === Number(sceneId);
});
if (!scene) return;
const preview = event.currentTarget
? event.currentTarget.closest(".sb-image-preview")
: null;
if (!preview) return;
const rect = preview.getBoundingClientRect();
storyboardFrameResizeState = {
sceneId: sceneId,
edge: edge,
previewLeft: rect.left,
previewTop: rect.top,
previewWidth: rect.width,
previewHeight: rect.height
};
if (event.currentTarget.setPointerCapture) {
try {
event.currentTarget.setPointerCapture(event.pointerId);
} catch (captureError) {
console.warn("Frame resize pointer capture unavailable:", captureError);
}
}
document.addEventListener("pointermove", window.storyboardHandleFrameResize);
document.addEventListener("pointerup", window.storyboardEndFrameResize);
document.addEventListener("pointercancel", window.storyboardEndFrameResize);
};
window.storyboardHandleFrameResize = function(event) {
const state = storyboardFrameResizeState;
if (!state) return;
const scene = storyboardScenes.find(function(item) {
return Number(item.id) === Number(state.sceneId);
});
if (!scene) return;
let width = Number(scene.frameWidth || 80);
let height = Number(scene.frameHeight || 80);
if (state.edge === "right" || state.edge === "corner") {
width = ((event.clientX - state.previewLeft) / Math.max(1, state.previewWidth)) * 100;
}
if (state.edge === "bottom" || state.edge === "corner") {
height = ((event.clientY - state.previewTop) / Math.max(1, state.previewHeight)) * 100;
}
scene.frameWidth = Math.max(35, Math.min(100, width));
scene.frameHeight = Math.max(35, Math.min(100, height));
window.storyboardApplyFrameVisual(state.sceneId);
};
window.storyboardEndFrameResize = function() {
if (!storyboardFrameResizeState) return;
storyboardFrameResizeState = null;
document.removeEventListener("pointermove", window.storyboardHandleFrameResize);
document.removeEventListener("pointerup", window.storyboardEndFrameResize);
document.removeEventListener("pointercancel", window.storyboardEndFrameResize);
window.storyboardUpdateStats();
};
window.storyboardUpdateScene = function(sceneId, field, value) {
const scene = storyboardScenes.find(s => s.id === sceneId);
if (!scene) return;
scene[field] = value;
window.storyboardUpdateStats();
};
