</div>`;
container.appendChild(card);
});
window.storyboardUpdateStats();
};
window.storyboardUpdateStats = function() {
const sceneCount = storyboardScenes.length;
let totalDuration = 0;
let totalCredits = 0;
storyboardScenes.forEach(scene => {
totalDuration += scene.duration || 5;
totalCredits += (scene.duration === 8) ? 24 : 15;
});
const sceneCountEl = document.getElementById('sbSceneCount');
const durationEl = document.getElementById('sbTotalDuration');
const creditsEl = document.getElementById('sbTotalCredits');
const estimatedEl = document.getElementById('sbEstimatedCredits');
if (sceneCountEl) sceneCountEl.textContent = sceneCount;
if (durationEl) durationEl.textContent = totalDuration;
if (creditsEl) creditsEl.textContent = totalCredits;
if (estimatedEl) estimatedEl.textContent = totalCredits;
};
