window.storyboardGenerateImage = async function(sceneId) {
if (!(await window.checkGaveAIAuth())) return;
const scene = storyboardScenes.find(s => s.id === sceneId);
if (!scene) return;
storyboardActiveSceneId = sceneId;
window.storyboardSetActiveScene(sceneId);
window.storyboardSetStatus("🖼️ Image is generating for scene " + sceneId + "... Please wait.", "loading");
const storyOverview = document.getElementById('sbStoryOverview')?.value || '';
const mainCharacter = document.getElementById('sbMainCharacter')?.value || '';
const visualStyle = document.getElementById('sbVisualStyle')?.value || '';
const environment = document.getElementById('sbEnvironment')?.value || '';
const continuity = [storyOverview ? "Story: " + storyOverview : "", mainCharacter ? "Main Character: " + mainCharacter : "", visualStyle ? "Style: " + visualStyle : "", environment ? "Environment: " + environment : ""].filter(Boolean).join(". ");
const userScenePrompt = String(scene.prompt || "").trim();
const strictImagePrompt = window.wrapStrictPrompt("Scene: " + userScenePrompt + (continuity ? "\nMaintain this continuity:\n" + continuity : "") + "\n" + window.GAVEAI_FRAME_COMPOSITION_RULES, false);
try {
const data = await fetchJsonSafe(GAVEAI_BACKEND_URL + "/generate-image", { method: "POST", body: JSON.stringify({ prompt: strictImagePrompt }) });
const imageUrl = data.url || data.imageUrl || (data.generatedMedia && data.generatedMedia.url);
if (imageUrl) {
scene.imageUrl = imageUrl;
scene.firstFrameImage = imageUrl;
window.storyboardRenderScenes();
window.storyboardSetStatus("✅ Image generated successfully for scene " + sceneId + ".", "success");
} else {
window.storyboardSetStatus("❌ Image generation succeeded but no URL was returned.", "error");
}
} catch (error) {
console.error("Scene image generation error:", error);
window.storyboardSetStatus("❌ " + (error?.message || "Image generation failed."), "error");
}
};
window.storyboardUploadImage = function(sceneId) {
const input = document.createElement('input');
input.type = 'file';
input.accept = 'image/png,image/jpeg,image/webp';
input.onchange = async function() {
if (!input.files || !input.files[0]) return;
const file = input.files[0];
const scene = storyboardScenes.find(s => s.id === sceneId);
if (!scene) return;
window.storyboardSetStatus("📤 Uploading image for scene " + sceneId + "...", "loading");
try {
const url = await uploadToImageKit(file, 'image');
if (url) {
scene.imageUrl = url;
scene.firstFrameImage = url;
window.storyboardRenderScenes();
window.storyboardSetStatus("✅ Image uploaded successfully for scene " + sceneId + ".", "success");
} else {
window.storyboardSetStatus("❌ Upload succeeded but no URL was returned.", "error");
}
} catch (error) {
console.error("Scene image upload error:", error);
window.storyboardSetStatus("❌ " + (error?.message || "Image upload failed."), "error");
}
};
input.click();
};
window.storyboardUploadVideo = function(sceneId) {
const input = document.createElement("input");
input.type = "file";
input.accept = "video/mp4,video/webm,video/quicktime";
input.onchange = async function() {
if (!input.files || !input.files[0]) return;
const file = input.files[0];
const scene = storyboardScenes.find(function(item) { return Number(item.id) === Number(sceneId); });
if (!scene) {
console.error("GAVEAI: no active scene selected for video upload.");
window.storyboardSetStatus("❌ No active scene selected.", "error");
return;
}
window.storyboardSetStatus("📤 Uploading video for scene " + sceneId + "...", "loading");
try {
const url = await uploadToImageKit(file, "video");
if (url) {
scene.videoUrl = url;
window.storyboardRenderScenes();
window.storyboardSetStatus("✅ Video uploaded successfully for scene " + sceneId + ".", "success");
} else {
window.storyboardSetStatus("❌ Upload succeeded but no URL was returned.", "error");
}
} catch (error) {
console.error("GAVEAI scene video upload failed:", error);
window.storyboardSetStatus("❌ " + (error?.message || "Video upload failed."), "error");
}
};
input.click();
};
window.storyboardGenerateSingleVideo = async function() {
if (!(await window.checkGaveAIAuth())) return;
const sceneId = window.storyboardGetActiveSceneId ? window.storyboardGetActiveSceneId() : null;
if (sceneId === null) { window.storyboardSetStatus("❌ Please select a scene first.", "error"); return; }
const scene = storyboardScenes.find(s => s.id === sceneId);
if (!scene) { window.storyboardSetStatus("❌ Scene not found.", "error"); return; }
if (!scene.prompt || !String(scene.prompt).trim()) { window.storyboardSetStatus("❌ Please enter a prompt for this scene first.", "error"); return; }
window.storyboardSetStatus("🎬 Video is generating for scene " + sceneId + "... Please wait. It may take a few moments.", "loading");
try {
const storyOverview = document.getElementById('sbStoryOverview')?.value || '';
const mainCharacter = document.getElementById('sbMainCharacter')?.value || '';
const visualStyle = document.getElementById('sbVisualStyle')?.value || '';
const environment = document.getElementById('sbEnvironment')?.value || '';
const continuity = [storyOverview ? "Story: " + storyOverview : "", mainCharacter ? "Main Character: " + mainCharacter : "", visualStyle ? "Style: " + visualStyle : "", environment ? "Environment: " + environment : ""].filter(Boolean).join(". ");
const strictPrompt = window.wrapStrictPrompt("Scene: " + scene.prompt + (continuity ? "\nMaintain this continuity:\n" + continuity : ""), false);
const requestBody = {
prompt: strictPrompt + "\n" + window.GAVEAI_FRAME_COMPOSITION_RULES,
width: 480, height: 832, duration: scene.duration || 5, seed: -1,
firstFrameImage: scene.firstFrameImage || scene.imageUrl || null
};
const data = await fetchJsonSafe(GAVEAI_BACKEND_URL + "/generate-video", { method: "POST", body: JSON.stringify(requestBody) });
if (data.freeVideoRemaining !== undefined) { updateFreeVideoDisplay(data.freeVideoRemaining); }
const immediateVideoUrl = (data.generatedMedia && data.generatedMedia.video) || (data.generatedMedia && data.generatedMedia.url) || data.finalVideoUrl || data.videoUrl || data.url || "";
if (immediateVideoUrl) {
window.storyboardSetStatus("✅ Single video generated successfully for scene " + sceneId + ".", "success");
window.storyboardRenderSingleVideoResult(immediateVideoUrl, sceneId);
return;
}
const jobId = data.jobId || data.videoJobId || data.productionId || "";
if (!jobId) { throw new Error("GaveAI did not return a video job ID."); }
const pollingStartedAt = Date.now();
const pollingTimeoutMs = 15 * 60 * 1000;
while (true) {
if (Date.now() - pollingStartedAt >= pollingTimeoutMs) { throw new Error("Video generation is taking longer than expected."); }
await new Promise(function(resolve) { setTimeout(resolve, 3000); });
window.storyboardSetStatus("🎬 Video is generating for scene " + sceneId + "... Please wait. It may take a few moments.", "loading");
const statusData = await fetchJsonSafe(GAVEAI_BACKEND_URL + "/api/video-productions/" + encodeURIComponent(jobId), { method: "GET" });
const production = statusData && statusData.production ? statusData.production : statusData;
const productionStatus = String(production && production.status ? production.status : "").toLowerCase();
if (productionStatus === "queued" || productionStatus === "pending" || productionStatus === "generating" || productionStatus === "processing" || productionStatus === "running") { continue; }
if (productionStatus === "completed" || productionStatus === "complete" || productionStatus === "success" || productionStatus === "succeeded") {
const completedVideoUrl = production.videoUrl || production.finalVideoUrl || production.url || (production.generatedMedia && (production.generatedMedia.video || production.generatedMedia.url));
if (!completedVideoUrl) { throw new Error("Video generation completed, but GaveAI did not return the final video URL."); }
window.storyboardSetStatus("✅ Single video generated successfully for scene " + sceneId + ".", "success");
window.storyboardRenderSingleVideoResult(completedVideoUrl, sceneId);
return;
}
if (productionStatus === "failed" || productionStatus === "error" || productionStatus === "cancelled" || productionStatus === "canceled") {
throw new Error(production.error || "GaveAI could not generate the video. Please try again.");
}
}
} catch (error) {
console.error("Single video generation error:", error);
window.storyboardSetStatus("❌ " + (error && error.message ? String(error.message) : "GaveAI could not generate the video. Please try again."), "error");
}
};
/* [FIXED] Render single video result WITH download buttons IMMEDIATELY */
window.storyboardRenderSingleVideoResult = function(videoUrl, sceneId) {
const result = document.getElementById("sbSingleVideoResult");
