}
result.style.display = "block";
result.className = "sb-final-video-result";
result.innerHTML = '<div style="font-family:\'Poppins\',sans-serif;font-size:18px;font-weight:800;color:#1e3a8a;margin-bottom:16px;">🎬 Scene ' + sceneId + ' - Single Video</div>' +
'<video src="' + videoUrl + '" controls playsinline style="width:100%;max-width:800px;border-radius:12px;box-shadow:0 8px 24px rgba(0,0,0,0.1);margin:16px auto;display:block;"></video>' +
'<div class="sb-download-buttons">' +
'<a href="' + videoUrl + '" target="_blank" rel="noopener" class="sb-workspace-action">🔗 Open Video</a>' +
'<a href="#" onclick="event.preventDefault(); window.forceDownload(\'' + videoUrl + '\', \'gaveai-scene-' + sceneId + '-video.mp4\')" class="sb-workspace-action">💾 Download Video</a>' +
'</div>';
result.scrollIntoView({ behavior: 'smooth', block: 'center' });
};
window.storyboardSetStatus = function(message, type) {
