'</div>';
result.scrollIntoView({ behavior: 'smooth', block: 'center' });
};
window.storyboardGenerateFinal = async function() {
if (!(await window.checkGaveAIAuth())) return;
if (storyboardScenes.length === 0) { window.storyboardSetStatus("❌ Please add at least one scene.", "error"); return; }
const btn = document.getElementById("sbGenerateFinalBtn");
if (btn) { btn.disabled = true; btn.innerHTML = "⏳ Final connected video is generating... Please wait. This may take a few moments."; }
const storyOverview = document.getElementById("sbStoryOverview")?.value || "";
const mainCharacter = document.getElementById("sbMainCharacter")?.value || "";
const supportingCharacters = document.getElementById("sbSupportingCharacters")?.value || "";
const visualStyle = document.getElementById("sbVisualStyle")?.value || "";
const environment = document.getElementById("sbEnvironment")?.value || "";
const cameraStyle = document.getElementById("sbCameraStyle")?.value || "";
const globalAudioDirection = document.getElementById("sbGlobalAudio")?.value || "";
const scenePrompts = storyboardScenes.map(function(scene, index) {
const prompt = String(scene.prompt || "").trim();
if (!prompt) {
return "Scene " + (index + 1) + ": Continue the connected story using the available scene context.";
}
return "Scene " + (index + 1) + ": " + prompt;
}).join("\n");
const storyboardFrameRules = window.GAVEAI_FRAME_COMPOSITION_RULES;
const storyboardPrompt = window.wrapStrictPrompt("STORY OVERVIEW:\n" + storyOverview + "\nMAIN CHARACTER:\n" + mainCharacter + "\nSUPPORTING CHARACTERS:\n" + supportingCharacters + "\nVISUAL STYLE:\n" + visualStyle + "\nENVIRONMENT:\n" + environment + "\nCAMERA STYLE:\n" + cameraStyle + "\nGLOBAL AUDIO DIRECTION:\n" + globalAudioDirection + "\nSCENE REQUESTS:\n" + scenePrompts + "\n" + storyboardFrameRules, false);
const payload = {
prompt: storyboardPrompt, storyOverview: storyOverview, mainCharacter: mainCharacter, supportingCharacters: supportingCharacters,
visualStyle: visualStyle, environment: environment, cameraStyle: cameraStyle, globalAudioDirection: globalAudioDirection,
scenes: storyboardScenes.map(function(scene) {
return {
prompt: String(scene.prompt || "").trim(),
duration: scene.duration || 5,
firstFrameImage: scene.firstFrameImage || scene.imageUrl || null,
lastFrameImage: scene.lastFrameImage || null,
videoUrl: scene.videoUrl || null,
frameWidth: Math.max(35, Math.min(100, Number(scene.frameWidth || 80))),
frameHeight: Math.max(35, Math.min(100, Number(scene.frameHeight || 80))),
voiceText: scene.voiceText || scene.dialogue || scene.narration || "",
dialogue: scene.dialogue || "",
narration: scene.narration || "",
voiceEmotion: scene.voiceEmotion || "",
voiceSpeed: scene.voiceSpeed || 1.0,
voicePitch: scene.voicePitch || 0,
voiceLanguage: scene.voiceLanguage || null,
voiceId: scene.voiceId || null,
languageBoost: scene.languageBoost || null,
musicPrompt: scene.musicPrompt || "",
musicVolume: scene.musicVolume || 0.7,
sfxPrompt: scene.sfxPrompt || "",
sfxVolume: scene.sfxVolume || 0.7,
ambiencePrompt: scene.ambiencePrompt || "",
ambienceVolume: scene.ambienceVolume || 0.5
};
}), width: 480, height: 832, seed: -1
};
const totalCredits = storyboardScenes.reduce(function(sum, scene) { return sum + ((scene.duration === 8) ? 24 : 15); }, 0);
window.storyboardSetStatus("🎬 Final connected video is generating... (" + totalCredits + " credits, " + storyboardScenes.length + " scenes). This may take several minutes.", "loading");
try {
const data = await fetchJsonSafe(GAVEAI_BACKEND_URL + "/api/storyboard/generate", { method: "POST", body: JSON.stringify(payload) });
if (data.freeVideoRemaining !== undefined) { updateFreeVideoDisplay(data.freeVideoRemaining); }
const immediateVideoUrl = (data.generatedMedia && data.generatedMedia.video) || (data.generatedMedia && data.generatedMedia.url) || data.finalVideoUrl || data.videoUrl || data.url;
if (immediateVideoUrl) {
window.storyboardRenderFinalVideo(immediateVideoUrl);
window.storyboardSetStatus("✅ Final connected video generated successfully. Audio embedded.", "success");
return;
}
const jobId = data.jobId || data.videoJobId || data.productionId || "";
if (!jobId) { throw new Error("GaveAI did not return a video production job ID."); }
const pollingStartedAt = Date.now();
const pollingTimeoutMs = 15 * 60 * 1000;
const pollingIntervalMs = 3000;
while (true) {
if (Date.now() - pollingStartedAt >= pollingTimeoutMs) { throw new Error("Video generation is taking longer than expected. Please check the Storyboard workspace again shortly."); }
await new Promise(function(resolve) { setTimeout(resolve, pollingIntervalMs); });
const statusData = await fetchJsonSafe(GAVEAI_BACKEND_URL + "/api/video-productions/" + encodeURIComponent(jobId), { method: "GET" });
const production = statusData && statusData.production ? statusData.production : statusData;
const productionStatus = String(production && production.status ? production.status : "").toLowerCase();
if (productionStatus === "queued" || productionStatus === "pending") { window.storyboardSetStatus("🎬 Your connected video is queued. Please wait...", "loading"); continue; }
if (productionStatus === "generating" || productionStatus === "processing" || productionStatus === "running") { window.storyboardSetStatus("🎬 Final connected video is generating... Please wait. This may take a few moments.", "loading"); continue; }
if (productionStatus === "completed" || productionStatus === "complete" || productionStatus === "success" || productionStatus === "succeeded") {
const completedVideoUrl = production.videoUrl || production.finalVideoUrl || production.url || (production.generatedMedia && (production.generatedMedia.video || production.generatedMedia.url));
if (!completedVideoUrl) { throw new Error("Video generation completed, but GaveAI did not return the final video URL."); }
window.storyboardRenderFinalVideo(completedVideoUrl);
window.storyboardSetStatus("✅ Final connected video generated successfully. Audio embedded.", "success");
if (production.freeVideoRemaining !== undefined) { updateFreeVideoDisplay(production.freeVideoRemaining); }
return;
}
if (productionStatus === "failed" || productionStatus === "error" || productionStatus === "cancelled" || productionStatus === "canceled") {
throw new Error(production.error || "GaveAI could not generate the final connected video. Please try again.");
}
window.storyboardSetStatus("🎬 Final connected video is generating... Please wait. This may take a few moments.", "loading");
}
} catch (error) {
console.error("Final video generation error:", error);
window.storyboardSetStatus(error && error.message ? "❌ " + String(error.message) : "❌ GaveAI could not generate the final connected video. Please try again.", "error");
} finally {
if (btn) { btn.disabled = false; btn.innerHTML = "🎬 Generate Final Connected Video"; }
}
};
