let gmtUserReferralCode = '';
let gmtUserReferralLink = '';
function getGmtIncomingReferralCode() {
try {
const params = new URLSearchParams(window.location.search || '');
return String(params.get('ref') || '').trim();
} catch (error) {
console.warn('Unable to read referral code from URL:', error);
return '';
}
}
function buildGmtCareerHubReferralUrl() {
const baseUrl = 'https://gavemoneytips.blogspot.com/p/account-gave-money-tips.html';
try {
const incomingReferralCode = getGmtIncomingReferralCode();
if (!incomingReferralCode) {
return baseUrl;
}
return baseUrl + '?ref=' + encodeURIComponent(incomingReferralCode);
} catch (error) {
console.warn('Unable to preserve referral code for Career Hub navigation:', error);
return baseUrl;
}
}
function openGmtCareerHubWithReferral() {
window.location.href = buildGmtCareerHubReferralUrl();
return false;
}
function buildGmtReferralLink(code) {
const normalizedCode = String(code || '').trim();
if (!normalizedCode) {
return '';
}
return window.location.origin + '/?ref=' + encodeURIComponent(normalizedCode);
}
function renderGmtReferralInfo() {
const codeInput = document.getElementById('gmt-user-referral-code-input');
const linkInput = document.getElementById('gmt-user-referral-link-input');
if (codeInput) {
codeInput.value = gmtUserReferralCode || '';
codeInput.placeholder = gmtUserReferralCode ? '' : 'Sign in to load your referral code';
}
if (linkInput) {
linkInput.value = gmtUserReferralLink || '';
linkInput.placeholder = gmtUserReferralLink ? '' : 'Sign in to load your referral link';
}
}
async function initializeGmtReferral(user) {
gmtUserReferralCode = '';
gmtUserReferralLink = '';
renderGmtReferralInfo();
if (!user) {
return;
}
try {
const headers = await getGaveAIAuthHeaders(false);
const incomingReferralCode = getGmtIncomingReferralCode();
const response = await fetch(
GAVEAI_BACKEND_URL + '/api/referral/initialize',
{
method: 'POST',
headers: headers,
body: JSON.stringify({
referralCode: incomingReferralCode
})
}
);
const data = await response.json().catch(() => ({}));
if (!response.ok || !data || data.success !== true) {
throw new Error(
data && data.error
? data.error
: 'Unable to initialize referral information.'
);
}
gmtUserReferralCode = String(data.referralCode || '').trim();
gmtUserReferralLink = buildGmtReferralLink(gmtUserReferralCode);
renderGmtReferralInfo();
console.log('GaveAI referral initialized:', gmtUserReferralCode);
} catch (error) {
console.warn('GaveAI referral initialization failed:', error);
renderGmtReferralInfo();
}
}
async function copyGmtReferralCode() {
const input = document.getElementById('gmt-user-referral-code-input');
const status = document.getElementById('gmt-referral-share-status');
if (!input || !input.value) {
return;
}
try {
await navigator.clipboard.writeText(input.value);
if (status) {
status.textContent = 'Referral code copied.';
setTimeout(function() {
status.textContent = '';
}, 2200);
}
} catch (error) {
input.focus();
input.select();
try {
document.execCommand('copy');
if (status) {
status.textContent = 'Referral code copied.';
setTimeout(function() {
status.textContent = '';
}, 2200);
}
} catch (copyError) {
if (status) {
status.textContent = 'Please copy the referral code manually.';
}
}
}
}
