setTimeout(function() {
status.textContent = '';
}, 2200);
}
} catch (copyError) {
if (status) {
status.textContent = 'Please copy the referral link manually.';
}
}
}
}
let gmtActiveReferralCompetition = null;
function formatReferralCompetitionNumber(value) {
const number = Number(value);
if (!Number.isFinite(number)) return '0';
return Math.max(0, Math.floor(number)).toLocaleString();
}
function formatReferralCompetitionDate(value) {
if (!value) return '—';
const date = new Date(value);
if (Number.isNaN(date.getTime())) {
return '—';
}
return date.toLocaleString(undefined, {
year: 'numeric',
month: 'short',
day: 'numeric',
hour: 'numeric',
minute: '2-digit'
});
}
function hideSiteAnnouncement() {
const announcement = document.getElementById('gmt-site-announcement');

if (announcement) {
announcement.classList.remove('open');
announcement.classList.remove('type-info');
announcement.classList.remove('type-warning');
announcement.classList.remove('type-maintenance');
announcement.classList.remove('type-success');
}
}

function renderSiteAnnouncement(data) {
const announcement = document.getElementById('gmt-site-announcement');

if (!announcement || !data || data.enabled !== true) {
hideSiteAnnouncement();
return;
}

const allowedTypes = ['info','warning','maintenance','success'];
const type = allowedTypes.includes(String(data.type || '').trim().toLowerCase())
? String(data.type || '').trim().toLowerCase()
: 'info';

const title = String(data.title || '').trim();
const message = String(data.message || '').trim();
const service = String(data.service || '').trim();

if (!title || !message) {
hideSiteAnnouncement();
return;
}

const badge = document.getElementById('gmt-site-announcement-badge');
const titleElement = document.getElementById('gmt-site-announcement-title');
const serviceElement = document.getElementById('gmt-site-announcement-service');
const messageElement = document.getElementById('gmt-site-announcement-message');

const typeLabels = {
info: 'Site Notice',
warning: 'Service Notice',
maintenance: 'Maintenance Notice',
success: 'Service Update'
};

const typeIcons = {
info: 'ℹ️',
warning: '⚠️',
maintenance: '🔧',
success: '✅'
};

announcement.classList.remove('type-info');
announcement.classList.remove('type-warning');
announcement.classList.remove('type-maintenance');
announcement.classList.remove('type-success');
announcement.classList.add('type-' + type);

if (badge) {
badge.textContent = typeIcons[type] + ' ' + typeLabels[type];
}

if (titleElement) {
titleElement.textContent = title;
}

if (serviceElement) {
serviceElement.textContent = service ? 'Service: ' + service : '';
serviceElement.style.display = service ? 'block' : 'none';
}

if (messageElement) {
messageElement.textContent = message;
}

announcement.classList.add('open');
}

async function loadSiteAnnouncement() {
const announcement = document.getElementById('gmt-site-announcement');

if (!announcement) {
return;
}

try {
const response = await fetch(
GAVEAI_BACKEND_URL + '/api/site-announcement',
{
method: 'GET',
headers: {
'Accept': 'application/json'
},
cache: 'no-store'
}
);

if (!response.ok) {
throw new Error('Site announcement request failed: ' + response.status);
}

const data = await response.json();

if (
!data ||
data.success !== true ||
!data.announcement
) {
hideSiteAnnouncement();
return;
}

renderSiteAnnouncement(data.announcement);
} catch (error) {
console.warn(
'Gave Money Tips site announcement could not be loaded:',
error
);
hideSiteAnnouncement();
}
}
function hideReferralCompetitionAnnouncement() {
const announcement = document.getElementById('gmt-referral-announcement');
if (announcement) {
announcement.classList.remove('open');
}
gmtActiveReferralCompetition = null;
}
function getReferralPlacementBadge(placement) {
const value = Number(placement);

if (value === 1) {
return '\u{1F947} 1st Place';
}

if (value === 2) {
return '\u{1F948} 2nd Place';
}

if (value === 3) {
return '\u{1F949} 3rd Place';
}

if (Number.isFinite(value) && value > 0) {
const suffix =
value % 100 >= 11 && value % 100 <= 13
? 'th'
: value % 10 === 1
? 'st'
: value % 10 === 2
? 'nd'
: value % 10 === 3
? 'rd'
: 'th';

return value + suffix + ' Place';
}

return '';
}

function renderActiveReferralCompetition(competition) {
const announcement =
document.getElementById(
'gmt-referral-announcement'
);

if (!announcement || !competition) {
hideReferralCompetitionAnnouncement();
return;
}

const requiredReferrals = Math.max(
1,
Math.floor(Number(competition.requiredReferrals) || 1)
);

const rewardCredits = Math.max(
0,
Math.floor(Number(competition.rewardCredits) || 0)
);

const rewardDurationMonths = Math.max(
0,
Math.floor(Number(competition.rewardDurationMonths) || 0)
);

const badge =
document.getElementById(
'gmt-referral-announcement-badge'
);

const title =
document.getElementById(
'gmt-referral-announcement-title'
);

const sub =
document.getElementById(
'gmt-referral-announcement-sub'
);

const leaderboard =
Array.isArray(competition.leaderboard)
? competition.leaderboard
: [];

const winner =
competition.winner &&
typeof competition.winner === 'object'
? competition.winner
: null;

if (badge) {
let badgeText =
'\u{1F3C6} Referral Contest';

if (winner && winner.displayName) {
badgeText +=
' \u2022 \u{1F451} Winner';
} else if (leaderboard.length > 0) {
const firstPlacement =
getReferralPlacementBadge(
leaderboard[0].placement
);

if (firstPlacement) {
badgeText +=
' \u2022 ' + firstPlacement;
}
}

badge.textContent = badgeText;
}

if (title) {
if (winner && winner.displayName) {
title.textContent =
'\u{1F451} Winner: ' +
String(winner.displayName) +
' \u2022 ' +
formatReferralCompetitionNumber(
winner.referralCount
) +
' qualified referrals';
} else {
title.textContent =
'Refer ' +
formatReferralCompetitionNumber(
requiredReferrals
) +
' people to choose a plan and earn ' +
formatReferralCompetitionNumber(
rewardCredits
) +
' credits!';
}
}

if (sub) {
const placementText =
leaderboard
.slice(0, 3)
.map((entry) => {
const placement =
getReferralPlacementBadge(
entry.placement
);

return placement
? placement +
' \u2022 ' +
formatReferralCompetitionNumber(
entry.referralCount
) +
' qualified'
: '';
})
.filter(Boolean)
.join(' | ');

if (winner && winner.displayName) {
sub.textContent =
'Contest winner: ' +
String(winner.displayName) +
'. Results remain visible for the contest result period. Click for full details.';
} else if (placementText) {
sub.textContent =
placementText +
'. Complete the required qualifying referrals during the contest period.' +
(
rewardDurationMonths > 0
? ' Reward duration: ' +
formatReferralCompetitionNumber(
rewardDurationMonths
) +
(
rewardDurationMonths === 1
? ' month.'
: ' months.'
)
: ''
) +
' Click for full details.';
} else if (rewardDurationMonths > 0) {
sub.textContent =
'Complete the required qualifying referrals during the contest period. Reward duration: ' +
formatReferralCompetitionNumber(
rewardDurationMonths
) +
(
rewardDurationMonths === 1
? ' month.'
: ' months.'
) +
' Click for full details.';
} else {
sub.textContent =
'Complete the required qualifying referrals during the contest period. Click for full contest details.';
}
}

announcement.classList.add('open');
}

async function loadActiveReferralCompetition() {
const announcement =
document.getElementById(
'gmt-referral-announcement'
);

if (!announcement) {
return;
}

try {
const response = await fetch(
GAVEAI_BACKEND_URL +
'/api/referral/active',
{
method: 'GET',
headers: {
'Accept': 'application/json'
},
cache: 'no-store'
}
);

if (!response.ok) {
throw new Error(
'Referral competition request failed: ' +
response.status
);
}

const data = await response.json();

if (
data &&
data.success === true &&
data.competition
) {
gmtActiveReferralCompetition =
data.competition;

renderActiveReferralCompetition(
gmtActiveReferralCompetition
);

return;
}

const latestResponse = await fetch(
GAVEAI_BACKEND_URL +
'/api/referral/latest',
{
method: 'GET',
headers: {
'Accept': 'application/json'
},
cache: 'no-store'
}
);

if (!latestResponse.ok) {
throw new Error(
'Latest referral competition request failed: ' +
latestResponse.status
);
}

const latestData =
await latestResponse.json();

if (
!latestData ||
latestData.success !== true ||
!latestData.competition
) {
hideReferralCompetitionAnnouncement();
return;
}

gmtActiveReferralCompetition =
latestData.competition;

renderActiveReferralCompetition(
gmtActiveReferralCompetition
);

} catch (error) {
console.warn(
'Gave Money Tips referral competition could not be loaded:',
error
);

hideReferralCompetitionAnnouncement();
}
}
