function toggleFaq(element) { element.classList.toggle('active'); }
function loadCategoryPosts(label, containerId) {
const container = document.getElementById(containerId);
if (!container) return;
const script = document.createElement('script');
const encodedLabel = encodeURIComponent(label);
script.src = '/feeds/posts/summary/-/' + encodedLabel + '?alt=json-in-script&callback=cb_' + containerId.replace(/-/g,'_') + '&max-results=4';
window['cb_' + containerId.replace(/-/g,'_')] = function(data) {
container.innerHTML = '';
const entries = data ? (data.feed ? data.feed.entry : null) : null;
if (!entries || entries.length === 0) { container.innerHTML = '<div class="mini-card-placeholder">New Guide Coming Soon</div>'; return; }
entries.forEach(entry => {
let title = entry.title.$t;
let postUrl = '';
entry.link.forEach(link => { if (link.rel === 'alternate') postUrl = link.href; });
let imgUrl = 'https://via.placeholder.com/320x180?text=Gave+Money+Tips';
if (entry.media$thumbnail) { imgUrl = entry.media$thumbnail.url.replace('/s72-c/', '/w320-h180-c/'); }
const card = document.createElement('div');
card.className = 'mini-card';
card.innerHTML = '<a class="mini-card-img" href="' + postUrl + '"><img src="' + imgUrl + '" alt="' + title + '" loading="lazy" /></a><div class="mini-card-body"><div class="mini-card-title"><a href="' + postUrl + '">' + title + '</a></div><a class="mini-card-read" href="' + postUrl + '">Read Guide →</a></div>';
container.appendChild(card);
});
};
document.head.appendChild(script);
}
function setupAutocomplete(inputId, dropdownId) {
const input = document.getElementById(inputId);
const dropdown = document.getElementById(dropdownId);
if (!input || !dropdown) return;
input.addEventListener('input', function() {
const val = this.value.trim().toLowerCase();
if (val.length < 2) { dropdown.classList.remove('active'); return; }
const matches = verifiedCompaniesList.filter(j => j.title.toLowerCase().includes(val) || j.company.toLowerCase().includes(val) || j.category.toLowerCase().includes(val)).slice(0, 5);
dropdown.innerHTML = '';
if (matches.length === 0) { dropdown.classList.remove('active'); return; }
matches.forEach(item => {
const row = document.createElement('div');
row.className = 'autocomplete-item';
row.innerHTML = '<span> ' + item.title + ' <small style="color:#64748b;">(' + item.company + ')</small></span> <span class="item-type">' + item.category + '</span>';
row.addEventListener('click', function() { input.value = item.title; dropdown.classList.remove('active'); filterByKeyword(item.title); });
dropdown.appendChild(row);
});
dropdown.classList.add('active');
});
document.addEventListener('click', function(e) { if (!input.contains(e.target) && !dropdown.contains(e.target)) { dropdown.classList.remove('active'); } });
}
